#include "ui.h"
#include <3ds.h>
#include <citro2d.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

static C3D_RenderTarget* top_target;
static C3D_RenderTarget* bottom_target;
static C2D_TextBuf text_buf;
static const u32 BG=C2D_Color32(0,0,0,255),P1=C2D_Color32(8,8,10,255),P2=C2D_Color32(14,14,18,255),W=C2D_Color32(255,255,255,255),G=C2D_Color32(150,150,150,255),DG=C2D_Color32(52,52,58,255),CY=C2D_Color32(125,211,252,255),GR=C2D_Color32(134,239,172,255),Y=C2D_Color32(253,224,71,255),PU=C2D_Color32(216,180,254,255),OR=C2D_Color32(251,146,60,255),R=C2D_Color32(248,113,113,255);
static u32 pc(const char*s,u32 f){if(!s||!*s)return f;if(!strcmp(s,"white"))return W;if(!strcmp(s,"black"))return BG;if(!strcmp(s,"cyan"))return CY;if(!strcmp(s,"green"))return GR;if(!strcmp(s,"yellow"))return Y;if(!strcmp(s,"purple"))return PU;if(!strcmp(s,"orange"))return OR;if(!strcmp(s,"red"))return R;if(!strcmp(s,"#dddddd"))return C2D_Color32(221,221,221,255);if(!strcmp(s,"#111111"))return C2D_Color32(17,17,17,255);return f;}
static void ol(float x,float y,float w,float h,u32 c){C2D_DrawRectSolid(x,y,0,w,1,c);C2D_DrawRectSolid(x,y+h-1,0,w,1,c);C2D_DrawRectSolid(x,y,0,1,h,c);C2D_DrawRectSolid(x+w-1,y,0,1,h,c);}
static void dt(float x,float y,float sc,u32 c,const char*t){if(!t||!*t)return;C2D_Text tx;C2D_TextParse(&tx,text_buf,t);C2D_TextOptimize(&tx);C2D_DrawText(&tx,C2D_WithColor,x,y,0,sc,sc,c);}
static u32 syn(const char*l){if(!l)return W;if(strstr(l,"<!--"))return G;if(strstr(l,"<style")||strstr(l,"</style")||strstr(l,"{")||strstr(l,"}"))return PU;if(strstr(l,"<script")||strstr(l,"</script"))return OR;if(strstr(l,"<")||strstr(l,">"))return CY;if(strstr(l,"\\\"")||strstr(l,"'"))return GR;return W;}
void ui_init(void){C3D_Init(C3D_DEFAULT_CMDBUF_SIZE);C2D_Init(C2D_DEFAULT_MAX_OBJECTS);C2D_Prepare();top_target=C2D_CreateScreenTarget(GFX_TOP,GFX_LEFT);bottom_target=C2D_CreateScreenTarget(GFX_BOTTOM,GFX_LEFT);text_buf=C2D_TextBufNew(8192);}
void ui_shutdown(void){if(text_buf){C2D_TextBufDelete(text_buf);text_buf=NULL;}C2D_Fini();C3D_Fini();}
bool ui_keyboard(Editor*e,AppState*a){SwkbdState k;char in[1024];swkbdInit(&k,SWKBD_TYPE_NORMAL,2,sizeof(in)-1);swkbdSetHintText(&k,"Enter HTML/CSS/JS");swkbdSetButton(&k,SWKBD_BUTTON_LEFT,"Cancel",false);swkbdSetButton(&k,SWKBD_BUTTON_RIGHT,"Insert",true);SwkbdButton b=swkbdInputText(&k,in,sizeof(in));if(b==SWKBD_BUTTON_RIGHT){if(editor_insert(e,in)){app_status(a,"Inserted text.");return true;}app_status(a,"Insert failed: buffer full.");}else app_status(a,"Keyboard canceled.");return false;}
void ui_draw_top(const AppState*a,const EngineDoc*d){C3D_FrameBegin(C3D_FRAME_SYNCDRAW);C2D_TextBufClear(text_buf);C2D_TargetClear(top_target,BG);C2D_SceneBegin(top_target);C2D_DrawRectSolid(0,0,0,TOP_W,TOP_H,BG);C2D_DrawRectSolid(4,4,0,392,232,P1);ol(4,4,392,232,W);dt(10,8,.43f,CY,"Pocket Compiler v0.11");if(d&&d->title[0])dt(10,24,.34f,W,d->title);C2D_DrawRectSolid(8,42,0,384,140,BG);ol(8,42,384,140,DG);if(d){int v=d->box_count;if(v>70)v=70;for(int i=0;i<v;i++){const LayoutBox*b=&d->boxes[i];int x=10+b->x,y=44+b->y,w=b->w,h=b->h;if(x>388||y>180||w<4||h<4)continue;if(x+w>390)w=390-x;if(y+h>180)h=180-y;if(b->type==BOX_TEXT)dt((float)x,(float)y,.34f,pc(b->color,W),b->text);else if(b->type==BOX_IMAGE){C2D_DrawRectSolid((float)x,(float)y,0,(float)w,(float)h,C2D_Color32(20,24,32,255));ol((float)x,(float)y,(float)w,(float)h,CY);dt((float)x+6,(float)y+16,.32f,CY,"[image]");}else{C2D_DrawRectSolid((float)x,(float)y,0,(float)w,(float)h,pc(b->background,C2D_Color32(4,4,6,255)));ol((float)x,(float)y,(float)w,(float)h,DG);}}char m[180];snprintf(m,sizeof(m),"DOM:%d CSS:%d JS:%d Img:%d Res:%d",d->node_count,d->css_count,d->script_count,d->image_box_count,d->resources.count);dt(10,188,.34f,Y,m);snprintf(m,sizeof(m),"Cache:%d Fail:%d gzip/js/img enabled",d->resources.cached_count,d->resources.failed_count);dt(10,204,.32f,G,m);dt(10,220,.30f,d->error_count?R:G,d->error_count?"Diagnostics present - press X":"A Run  X Check  START Exit");}(void)a;}
void ui_draw_bottom(const AppState*a,const Editor*e){C2D_TargetClear(bottom_target,BG);C2D_SceneBegin(bottom_target);C2D_DrawRectSolid(0,0,0,BOT_W,BOT_H,BG);C2D_DrawRectSolid(4,4,0,312,232,P2);ol(4,4,312,232,W);dt(8,8,.32f,CY,"A Run X Check Y Save B Load SELECT Type");C2D_DrawRectSolid(8,26,0,304,184,BG);ol(8,26,304,184,DG);const char*q=e?e->text:"";int ln=0,row=0;while(*q&&row<16){const char*s=q;int len=0;while(q[len]&&q[len]!='\\n')len++;if(!e||ln>=e->scroll_line){char line[96];int n=len<76?len:76;memcpy(line,s,n);line[n]=0;char num[12];snprintf(num,sizeof(num),"%02d",ln+1);float y=30.0f+row*11.0f;dt(12,y,.27f,G,num);dt(34,y,.27f,syn(line),line);row++;}q+=len;if(*q=='\\n')q++;ln++;}while(row<16){dt(34,30.0f+row*11.0f,.27f,DG,"~");row++;}char st[160];snprintf(st,sizeof(st),"Len:%lu Cur:%lu Dirty:%s",e?(unsigned long)e->len:0,e?(unsigned long)e->cursor:0,a&&a->dirty?"yes":"no");dt(8,216,.30f,Y,st);if(a&&a->status[0])dt(8,228,.27f,W,a->status);C3D_FrameEnd(0);}
